+fn lathe() -> Machine {
+    Machine {
+        model: "TestBench lathe".into(),
+        vendor: "Camcraft Testbench".into(),
+        kind: Some("lathe".into()),
+        spindle_min: Some(25.0),
+        spindle_max: Some(12000.0),
+        ..Default::default()
+    }
+}
